(x, y, t) => {
  const cx = 240, cy = 120;
  const w1x = Math.sin(x*0.015+t*0.2)*20 + Math.cos(y*0.012-t*0.15)*15;
  const w1y = Math.cos(y*0.018-t*0.18)*20 + Math.sin(x*0.014+t*0.22)*15;
  const w2x = Math.sin((x+w1x)*0.02+t*0.35)*10 + Math.cos((y+w1y)*0.025-t*0.3)*8;
  const w2y = Math.cos((y+w1y)*0.022-t*0.32)*10 + Math.sin((x+w1x)*0.019+t*0.38)*8;
  const sx = x+w1x+w2x, sy = y+w1y+w2y;
  const src = [];
  for (let i = 0; i < 9; i++) {
    const a = i*Math.PI*2/9 + t*(0.15+i*0.05);
    const r = 80+Math.sin(t*0.3+i*1.2)*40+i*8;
    src.push([cx+Math.cos(a)*r+Math.sin(t*0.4+i*2)*30, cy+Math.sin(a)*r+Math.cos(t*0.35+i*1.5)*25, 0.04+(i%3)*0.03, 1.2+Math.sin(i*0.8)*0.8]);
  }
  let aS=0, iS=0, fS=0;
  for (const [sX,sY,f,sp] of src) {
    const d = Math.sqrt((sx-sX)**2+(sy-sY)**2);
    aS += Math.sin(d*f-t*sp);
    iS += Math.sin(d*f*0.7+t*sp*0.6+1.5);
    fS += Math.sin(d*f*1.4-t*sp*1.3+0.8)*0.5;
  }
  const act=aS/9, inh=iS/9, fine=fS/9;
