  const bg2 = (Math.sin((sx+sy)*0.1+t*2.2)+Math.sin((sx-sy)*0.085-t*1.8))*0.25;
  const bg3 = Math.sin(sx*0.06+Math.cos(sy*0.05+t)*3+t*1.5)*0.15;
  const bg = bg1+bg2+bg3;
  const dist = Math.sqrt((sx-cx)**2+(sy-cy)**2), ang = Math.atan2(sy-cy, sx-cx);
