  const radial = Math.sin(dist*0.08-t*0.9)*Math.cos(ang*2+t*0.5)*0.2;
  const feed = act-inh*0.65+bg*0.25+spiral+radial+fine*0.3;
  const reaction = Math.tanh(feed*2);
  const cell = Math.tanh((Math.sin(sx*0.13)*Math.sin(sy*0.13)+Math.sin((sx+sy)*0.09+t)*0.4)*1.8)*0.25;
  const micro = Math.sin(sx*0.25+sy*0.18+t*2.5)*Math.sin(sx*0.2-sy*0.22-t*1.8)*0.15;
  const blend = reaction*0.6+cell*0.2+micro*0.2, v = blend*0.5+0.5;
  const pal = [[5,8,42],[10,32,78],[16,68,108],[22,118,122],[50,155,108],[120,178,72],[195,190,55],[225,148,48],[218,92,52],[178,52,58],[125,28,68],[72,16,58],[32,10,50],[5,8,42]];
  const idx = v*(pal.length-1), i = Math.min(idx|0, pal.length-2), f = idx-i;
  const lum = 0.85+Math.sin(reaction*Math.PI)*0.15;
  const edge = Math.abs(reaction)>0.6?1.14:1.0;
  const glow = Math.max(0,reaction)*0.12;
